import heapq
from collections import deque

class Graph:
    def __init__(self):
        self.nodes_set = set()
        self.edges = {}

    def add_node(self, node):
        """Add a node to the graph."""
        self.nodes_set.add(node)
        if node not in self.edges:
            self.edges[node] = []

    def add_edge(self, a, b, weight):
        """Add an edge from a to b with given weight."""
        self.add_node(a)
        self.add_node(b)
        self.edges[a].append((b, weight))

    def neighbors(self, node):
        """Return list of (neighbor, weight) tuples for given node."""
        if node not in self.edges:
            return []
        return self.edges[node]

    def bfs(self, start):
        """Return nodes reachable from start in breadth-first order, visiting neighbors in sorted order."""
        if start not in self.nodes_set:
            raise KeyError("Start node not in graph")

        visited = set()
        queue = deque([start])
        result = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                result.append(node)
                # Add neighbors in sorted order
                neighbors = sorted(self.neighbors(node), key=lambda x: x[0])
                for neighbor, _ in neighbors:
                    if neighbor not in visited:
                        queue.append(neighbor)

        return result

    def shortest_path(self, a, b):
        """Return (cost, [a, ..., b]) for the cheapest path from a to b, or None if unreachable."""
        if a not in self.nodes_set or b not in self.nodes_set:
            raise KeyError("Node not in graph")

        # Dijkstra's algorithm
        distances = {node: float('inf') for node in self.nodes_set}
        distances[a] = 0
        previous = {}
        visited = set()

        # Priority queue: (distance, node)
        pq = [(0, a)]

        while pq:
            current_distance, current_node = heapq.heappop(pq)

            if current_node in visited:
                continue

            visited.add(current_node)

            if current_node == b:
                break

            # Check neighbors
            for neighbor, weight in self.neighbors(current_node):
                if neighbor not in visited:
                    new_distance = current_distance + weight

                    if new_distance < distances[neighbor]:
                        distances[neighbor] = new_distance
                        previous[neighbor] = current_node
                        heapq.heappush(pq, (new_distance, neighbor))

        # If we never reached b, it's unreachable
        if b not in visited:
            return None

        # Reconstruct path
        path = []
        current = b
        while current in previous:
            path.append(current)
            current = previous[current]
        path.append(a)
        path.reverse()

        return (distances[b], path)

